export type ViewState = 'HOME' | 'ABOUT' | 'PORTFOLIO' | 'CATEGORY' | 'ADMIN';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Instagram, 
  Linkedin, 
  Mail, 
  MessageCircle, 
  CheckCircle, 
  ExternalLink,
  Smartphone,
  Layout,
  Printer,
  ChevronDown,
  Github,
  Award,
  ArrowRight,
  ArrowLeft,
  Home,
  User,
  Briefcase,
  Palette,
  Sparkles,
  Settings,
  Plus,
  Trash2,
  BarChart3,
  Lock,
  LogOut,
  Save,
  Image as ImageIcon
} from 'lucide-react';
import { PortfolioCategory, ViewState, PortfolioItem, ContactInfo } from './types';
import { PORTFOLIO_ITEMS as INITIAL_ITEMS, SKILLS, CATEGORY_LABELS } from './constants';

const ADMIN_PASSWORD = "khaled_admin"; // Hardcoded for demo/private use

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [selectedCategory, setSelectedCategory] = useState<PortfolioCategory>(PortfolioCategory.SOCIAL_MEDIA);
  const [scrolled, setScrolled] = useState(false);

  // Admin State
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [passwordInput, setPasswordInput] = useState("");
  const [visitorCount, setVisitorCount] = useState(0);

  // Dynamic Content State
  const [items, setItems] = useState<PortfolioItem[]>(() => {
    const saved = localStorage.getItem('khaled_portfolio_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [contact, setContact] = useState<ContactInfo>(() => {
    const saved = localStorage.getItem('khaled_contact_info');
    return saved ? JSON.parse(saved) : {
      email: 'khaled.omar@example.com',
      whatsapp: '+201234567890',
      instagram: '#',
      linkedin: '#',
      github: '#'
    };
  });

  // Track Visitors (Simple persistence)
  useEffect(() => {
    const count = parseInt(localStorage.getItem('khaled_visitor_count') || '0');
    const newCount = count + 1;
    localStorage.setItem('khaled_visitor_count', newCount.toString());
    setVisitorCount(newCount);
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentView, selectedCategory]);

  const navigateToCategory = (cat: PortfolioCategory) => {
    setSelectedCategory(cat);
    setCurrentView('CATEGORY');
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => item.category === selectedCategory);
  }, [selectedCategory, items]);

  const marqueeItems = useMemo(() => {
    return [...items, ...items, ...items];
  }, [items]);

  // Admin Actions
  const handleLogin = () => {
    if (passwordInput === ADMIN_PASSWORD) {
      setIsLoggedIn(true);
      setShowLoginModal(false);
      setCurrentView('ADMIN');
      setPasswordInput("");
    } else {
      alert("كلمة المرور خاطئة");
    }
  };

  const addItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: PortfolioItem = {
      id: Date.now().toString(),
      title: formData.get('title') as string,
      imageUrl: formData.get('imageUrl') as string,
      description: formData.get('description') as string,
      category: formData.get('category') as PortfolioCategory,
    };
    const newItems = [newItem, ...items];
    setItems(newItems);
    localStorage.setItem('khaled_portfolio_items', JSON.stringify(newItems));
    e.currentTarget.reset();
    alert("تم إضافة العمل بنجاح");
  };

  const deleteItem = (id: string) => {
    if (confirm("هل أنت متأكد من حذف هذا العمل؟")) {
      const newItems = items.filter(i => i.id !== id);
      setItems(newItems);
      localStorage.setItem('khaled_portfolio_items', JSON.stringify(newItems));
    }
  };

  const saveContact = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newContact: ContactInfo = {
      email: formData.get('email') as string,
      whatsapp: formData.get('whatsapp') as string,
      instagram: formData.get('instagram') as string,
      linkedin: formData.get('linkedin') as string,
      github: formData.get('github') as string,
    };
    setContact(newContact);
    localStorage.setItem('khaled_contact_info', JSON.stringify(newContact));
    alert("تم تحديث بيانات التواصل");
  };

  const PortfolioGrid = ({ items }: { items: PortfolioItem[] }) => (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
      {items.map((item) => (
        <div key={item.id} className="group relative bg-zinc-900 rounded-3xl overflow-hidden aspect-[4/3] portfolio-card border border-zinc-800">
          <img 
            src={item.imageUrl} 
            alt={item.title} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
          />
          <div className="overlay absolute inset-0 bg-gradient-to-t from-zinc-950 via-zinc-950/40 to-transparent opacity-0 transition-opacity duration-300 flex flex-col justify-end p-8">
            <div className="transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 text-right">
              <span className="text-amber-500 text-xs font-black uppercase tracking-widest mb-2 block">
                {CATEGORY_LABELS[item.category]}
              </span>
              <h3 className="text-2xl font-black mb-2">{item.title}</h3>
              <p className="text-zinc-400 text-sm mb-6">{item.description}</p>
              <button className="bg-white/10 hover:bg-white/20 backdrop-blur-md text-white p-3 rounded-xl transition-all">
                <ExternalLink size={20} />
              </button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );

  return (
    <div className="min-h-screen selection:bg-amber-400/30 selection:text-amber-400 flex flex-col">
      {/* Navigation */}
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? 'bg-zinc-950/80 backdrop-blur-md py-4 border-b border-zinc-800' : 'bg-transparent py-6'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between">
          <button onClick={() => setCurrentView('HOME')} className="text-2xl font-black gradient-text tracking-tighter cursor-pointer">
            خالد عمر
          </button>
          <div className="hidden md:flex space-x-reverse space-x-8 items-center text-sm font-medium">
            <button onClick={() => setCurrentView('HOME')} className={`hover:text-amber-400 transition-colors ${currentView === 'HOME' ? 'text-amber-400' : ''}`}>الرئيسية</button>
            <button onClick={() => setCurrentView('ABOUT')} className={`hover:text-amber-400 transition-colors ${currentView === 'ABOUT' ? 'text-amber-400' : ''}`}>نبذة عني</button>
            <button onClick={() => setCurrentView('PORTFOLIO')} className={`hover:text-amber-400 transition-colors ${currentView === 'PORTFOLIO' ? 'text-amber-400' : ''}`}>معرض أعمالي</button>
            <div className="h-4 w-px bg-zinc-800"></div>
            {isLoggedIn && (
               <button onClick={() => setCurrentView('ADMIN')} className="text-amber-500 flex items-center gap-2 font-bold">
                 <Settings size={16} /> لوحة التحكم
               </button>
            )}
            <button onClick={() => {
              const el = document.getElementById('contact');
              el?.scrollIntoView({ behavior: 'smooth' });
            }} className="bg-zinc-900 border border-zinc-800 hover:border-amber-500/50 text-zinc-300 px-5 py-2 rounded-full font-bold transition-all">
              تواصل معي
            </button>
          </div>
        </div>
      </nav>

      <main className="flex-grow">
        {currentView === 'HOME' && (
          <div className="pt-24">
            {/* Hero Section */}
            <section id="home" className="relative min-h-[80vh] flex items-center overflow-hidden">
              <div className="absolute top-0 right-0 -z-10 w-[500px] h-[500px] bg-amber-500/10 blur-[120px] rounded-full" />
              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full">
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                  <div className="order-2 lg:order-1 text-right">
                    <span className="inline-block py-1 px-3 rounded-full bg-amber-500/10 text-amber-500 text-sm font-bold mb-6 border border-amber-500/20">
                      مبدع في حلول التصميم
                    </span>
                    <h1 className="text-5xl lg:text-8xl font-black mb-6 leading-tight">
                      <span className="gradient-text">خالد عمر</span>
                    </h1>
                    <p className="text-zinc-400 text-lg lg:text-xl leading-relaxed mb-10 max-w-2xl">
                      مصمم جرافيك متخصص في بناء العلامات التجارية والهويات البصرية الرقمية والمطبوعة. خبرة تمتد لسنوات في السوق العربي تضمن لك نتائج احترافية تتجاوز التوقعات.
                    </p>
                    <div className="flex flex-wrap gap-4 justify-end">
                      <button onClick={() => setCurrentView('PORTFOLIO')} className="bg-zinc-100 text-zinc-950 px-8 py-4 rounded-xl font-bold hover:bg-white transition-all transform hover:-translate-y-1">
                        استكشف معرض الأعمال
                      </button>
                      <button onClick={() => setCurrentView('ABOUT')} className="border border-zinc-700 text-zinc-300 px-8 py-4 rounded-xl font-bold hover:bg-zinc-800 transition-all transform hover:-translate-y-1">
                        اعرف المزيد عني
                      </button>
                    </div>
                  </div>
                  <div className="order-1 lg:order-2 flex justify-center lg:justify-end">
                    <div className="relative w-64 h-64 lg:w-[400px] lg:h-[400px]">
                      <div className="absolute inset-0 rounded-full border border-amber-500/20 animate-pulse" />
                      <div className="absolute inset-4 rounded-full border border-zinc-800" />
                      <img 
                        src="https://picsum.photos/seed/khaled2/600/600" 
                        alt="Khaled Omar" 
                        className="relative z-10 w-full h-full object-cover rounded-full shadow-2xl p-2 bg-zinc-950"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </section>

            {/* Specialty Quick Links */}
            <section className="py-20">
              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  {[
                    { id: PortfolioCategory.SOCIAL_MEDIA, icon: <Smartphone />, label: 'سوشيال ميديا', desc: 'بوستات وحملات' },
                    { id: PortfolioCategory.E_COMMERCE, icon: <Layout />, label: 'متاجر إلكترونية', desc: 'سلة، زد، وغيرها' },
                    { id: PortfolioCategory.PRINTS, icon: <Printer />, label: 'مطبوعات', desc: 'بروفايلات ومنشورات' },
                    { id: PortfolioCategory.VISUAL_IDENTITY, icon: <Palette />, label: 'هوية بصرية', desc: 'شعارات وبراندينج' }
                  ].map((specialty) => (
                    <button 
                      key={specialty.id}
                      onClick={() => navigateToCategory(specialty.id)}
                      className="glass-card p-8 rounded-[32px] text-right group hover:border-amber-500/30 transition-all transform hover:-translate-y-2"
                    >
                      <div className="bg-zinc-900 w-16 h-16 rounded-2xl flex items-center justify-center text-amber-500 mb-6 group-hover:bg-amber-500 group-hover:text-zinc-950 transition-all">
                        {specialty.icon}
