                      <h3 className="text-xl font-black mb-2">{specialty.label}</h3>
                      <p className="text-zinc-500 text-sm mb-6">{specialty.desc}</p>
                      <div className="flex items-center gap-2 text-amber-500 text-sm font-bold opacity-0 group-hover:opacity-100 transition-opacity">
                        <span>عرض الأعمال</span>
                        <ArrowLeft size={16} />
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            </section>

            {/* Marquee Strips */}
            <section className="py-20 bg-zinc-950 overflow-hidden marquee-container">
              <div className="mb-8">
                <div className="animate-marquee-left flex gap-4 pr-4">
                  {marqueeItems.slice(0, 15).map((item, idx) => (
                    <div key={idx} className="w-[300px] h-[200px] flex-shrink-0 rounded-2xl overflow-hidden border border-zinc-800">
                      <img src={item.imageUrl} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all" alt="" />
                    </div>
                  ))}
                </div>
              </div>
              <div>
                <div className="animate-marquee-right flex gap-4 pl-4">
                  {marqueeItems.slice(15, 30).map((item, idx) => (
                    <div key={idx} className="w-[300px] h-[200px] flex-shrink-0 rounded-2xl overflow-hidden border border-zinc-800">
                      <img src={item.imageUrl} className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all" alt="" />
                    </div>
                  ))}
                </div>
              </div>
            </section>

            {/* Brief About Me */}
            <section className="py-24 bg-zinc-900/30 relative">
              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
