export default App;

export enum PortfolioCategory {
  SOCIAL_MEDIA = 'SOCIAL_MEDIA',
  E_COMMERCE = 'E_COMMERCE',
  PRINTS = 'PRINTS',
  VISUAL_IDENTITY = 'VISUAL_IDENTITY'
}

export interface PortfolioItem {
  id: string;
  title: string;
  category: PortfolioCategory;
  subCategory: string;
  imageUrl: string;
  description: string;
  marqueeStrip?: 'none' | '1' | '2'; // Optional field to specify which home marquee strip it belongs to
}

export interface Skill {
  name: string;
  percentage: number;
}

export interface ContactInfo {
  email: string;
  whatsapp: string;
  instagram: string;
  linkedin: string;
  github: string;
}

export type ViewState = 'HOME' | 'ABOUT' | 'PORTFOLIO' | 'CATEGORY' | 'ADMIN';

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Instagram, 
  Linkedin, 
  Mail, 
  MessageCircle, 
  CheckCircle, 
  ExternalLink,
  Smartphone,
  Layout,
  Printer,
  ChevronDown,
  Github,
  Award,
  ArrowRight,
  ArrowLeft,
  Home,
  User,
  Briefcase,
  Palette,
  Sparkles,
  Settings,
  Plus,
  Trash2,
  BarChart3,
  Lock,
  LogOut,
  Save,
  Image as ImageIcon,
  X,
  Maximize2,
  Filter,
  Monitor
} from 'lucide-react';
import { PortfolioCategory, ViewState, PortfolioItem, ContactInfo } from './types';
import { PORTFOLIO_ITEMS as INITIAL_ITEMS, SKILLS, CATEGORY_LABELS, SUB_CATEGORIES } from './constants';

const ADMIN_PASSWORD = "khaled_admin";

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('HOME');
  const [selectedCategory, setSelectedCategory] = useState<PortfolioCategory>(PortfolioCategory.SOCIAL_MEDIA);
  const [selectedSubCategory, setSelectedSubCategory] = useState<string>('all');
  const [scrolled, setScrolled] = useState(false);

  // Lightbox State
  const [selectedImage, setSelectedImage] = useState<string | null>(null);

  // Admin State
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [passwordInput, setPasswordInput] = useState("");
  const [visitorCount, setVisitorCount] = useState(0);

  // Dynamic Content State
  const [items, setItems] = useState<PortfolioItem[]>(() => {
    const saved = localStorage.getItem('khaled_portfolio_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [contact, setContact] = useState<ContactInfo>(() => {
    const saved = localStorage.getItem('khaled_contact_info');
    return saved ? JSON.parse(saved) : {
      email: 'khaled.omar@example.com',
      whatsapp: '+201234567890',
      instagram: '#',
      linkedin: '#',
      github: '#'
    };
  });

  useEffect(() => {
    const count = parseInt(localStorage.getItem('khaled_visitor_count') || '0');
    const newCount = count + 1;
    localStorage.setItem('khaled_visitor_count', newCount.toString());
    setVisitorCount(newCount);
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [currentView, selectedCategory, selectedSubCategory]);

  const handleMainCategoryChange = (cat: PortfolioCategory) => {
    setSelectedCategory(cat);
    setSelectedSubCategory('all');
  };

  const navigateToCategory = (cat: PortfolioCategory) => {
    handleMainCategoryChange(cat);
    setCurrentView('CATEGORY');
  };

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchCategory = item.category === selectedCategory;
      const matchSub = selectedSubCategory === 'all' || item.subCategory === selectedSubCategory;
      return matchCategory && matchSub;
    });
  }, [selectedCategory, selectedSubCategory, items]);

  // Marquee Strip Logic
  const strip1Items = useMemo(() => {
    const filtered = items.filter(item => item.marqueeStrip === '1');
    // If empty, fallback to some items so the site doesn't look broken initially
    const source = filtered.length > 0 ? filtered : items.slice(0, 5);
    return [...source, ...source, ...source, ...source];
  }, [items]);

  const strip2Items = useMemo(() => {
    const filtered = items.filter(item => item.marqueeStrip === '2');
    const source = filtered.length > 0 ? filtered : items.slice(Math.max(0, items.length - 5));
    return [...source, ...source, ...source, ...source];
  }, [items]);

  // Admin Actions
  const handleLogin = () => {
    if (passwordInput === ADMIN_PASSWORD) {
      setIsLoggedIn(true);
      setShowLoginModal(false);
      setCurrentView('ADMIN');
      setPasswordInput("");
    } else {
      alert("كلمة المرور خاطئة");
    }
  };

  const addItem = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newItem: PortfolioItem = {
      id: Date.now().toString(),
      title: formData.get('title') as string || 'بدون عنوان',
      imageUrl: formData.get('imageUrl') as string,
      description: formData.get('description') as string || '',
