/**
 * Helper to convert Google Drive "Share" links to Direct Image URLs.
 * Standard link: https://drive.google.com/file/d/FILE_ID/view?usp=sharing
 * Direct link: https://drive.google.com/uc?export=view&id=FILE_ID
 */
const getDirectImageUrl = (url: string): string => {
  if (!url) return "";
  const driveRegex = /\/file\/d\/([a-zA-Z0-9_-]+)/;
  const driveIdMatch = url.match(driveRegex);

  if (driveIdMatch && driveIdMatch[1]) {
    return `https://drive.google.com/uc?export=view&id=${driveIdMatch[1]}`;
  }

  // Also handle links like https://drive.google.com/open?id=FILE_ID
  const driveOpenRegex = /id=([a-zA-Z0-9_-]+)/;
  const driveOpenMatch = url.match(driveOpenRegex);
  if (url.includes("drive.google.com") && driveOpenMatch && driveOpenMatch[1]) {
    return `https://drive.google.com/uc?export=view&id=${driveOpenMatch[1]}`;
  }

  return url;
};

