                               <Trash2 size={18} />
                             </button>
                             <button 
                                onClick={() => setEditingPortfolioItem(editingPortfolioItem === item.id ? null : item.id)} 
                                className="bg-zinc-800/90 text-white p-2.5 rounded-lg hover:bg-amber-500 transition-colors shadow-lg"
                                title="تعديل التصميم"
                             >
                               <Edit2 size={18} />
                             </button>
                          </div>
                        </div>

                        {editingPortfolioItem === item.id ? (
                          <div className="space-y-3 p-2 bg-zinc-950/50 rounded-xl">
                            <input 
                              id={`port-title-${item.id}`}
                              className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-xs" 
                              defaultValue={item.title}
                              placeholder="العنوان"
                            />
                            <input 
                              id={`port-url-${item.id}`}
                              className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-xs text-left" 
                              defaultValue={item.imageUrl}
                              placeholder="رابط الصورة"
                            />
                             <select 
                                id={`port-cat-${item.id}`}
                                className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-xs" 
                                defaultValue={item.category}
                              >
                                {Object.values(PortfolioCategory).map(cat => (
                                  <option key={cat} value={cat}>{CATEGORY_LABELS[cat]}</option>
                                ))}
                              </select>
                            <button 
                              onClick={() => {
                                const t = (document.getElementById(`port-title-${item.id}`) as HTMLInputElement).value;
                                const u = (document.getElementById(`port-url-${item.id}`) as HTMLInputElement).value;
                                const c = (document.getElementById(`port-cat-${item.id}`) as HTMLSelectElement).value as PortfolioCategory;
                                updatePortfolioItem(item.id, { title: t, imageUrl: getDirectImageUrl(u), category: c });
                              }}
                              className="w-full bg-emerald-600 text-white text-xs py-2.5 rounded-lg font-bold hover:bg-emerald-700 transition-colors"
                            >
                              حفظ التعديلات
                            </button>
                          </div>
                        ) : (
                          <div className="text-right px-1">
                            <div className="font-bold text-sm truncate mb-1">{item.title}</div>
                            <div className="text-[10px] text-zinc-500 flex items-center gap-2 justify-end">
                               {item.marqueeStrip !== 'none' && (
                                 <span className="text-amber-500 flex items-center gap-1 bg-amber-500/10 px-1.5 py-0.5 rounded">
                                   <Monitor size={10} /> شريط {item.marqueeStrip}
                                 </span>
                               )}
                               <span className="bg-zinc-800 px-1.5 py-0.5 rounded">{CATEGORY_LABELS[item.category]}</span>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                    {items.length === 0 && (
                      <div className="col-span-full py-20 border-2 border-dashed border-zinc-800 rounded-3xl text-center text-zinc-600">
                        معرض الأعمال فارغ حالياً
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </section>
        )}
      </main>

      {/* Contact Section */}
      <section id="contact" className="py-24 bg-zinc-950">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="bg-gradient-to-br from-zinc-900 to-zinc-950 border border-zinc-800 rounded-[40px] p-8 lg:p-20 overflow-hidden relative">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-amber-500 to-transparent"></div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
              <div className="text-right">
                <h2 className="text-4xl lg:text-5xl font-black mb-8">هل أنت مستعد <span className="text-amber-500">للبدء؟</span></h2>
                <div className="space-y-6">
                  <a href={`mailto:${contact.email}`} className="flex items-center gap-6 justify-end group">
                    <div className="text-xl font-bold group-hover:text-amber-500 transition-colors">{contact.email}</div>
                    <div className="bg-zinc-800 p-4 rounded-2xl text-amber-500"><Mail size={24} /></div>
                  </a>
                  <a href={`https://wa.me/${contact.whatsapp.replace(/\D/g,'')}`} className="flex items-center gap-6 justify-end group">
                    <div className="text-xl font-bold group-hover:text-emerald-500 transition-colors">{contact.whatsapp}</div>
                    <div className="bg-emerald-500/10 p-4 rounded-2xl text-emerald-500"><MessageCircle size={24} /></div>
                  </a>
                </div>
              </div>
              <div className="bg-zinc-950 p-8 rounded-[32px] border border-zinc-800">
                <form className="space-y-5 text-right" onSubmit={(e) => e.preventDefault()}>
                  <input type="text" className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 focus:border-amber-500/50 outline-none" placeholder="الاسم" />
                  <textarea rows={3} className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-4 py-3 focus:border-amber-500/50 outline-none" placeholder="مشروعك..." />
                  <button className="w-full bg-amber-500 text-zinc-950 font-black py-4 rounded-xl">إرسال</button>
                </form>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-12 bg-zinc-950 border-t border-zinc-900 text-center">
        <button onClick={() => setCurrentView('HOME')} className="text-3xl font-black gradient-text mb-6">خالد عمر</button>
        <p className="text-zinc-700 text-xs mb-4">© {new Date().getFullYear()} خالد عمر - جميع الحقوق محفوظة.</p>
        {!isLoggedIn && (
          <button onClick={() => setShowLoginModal(true)} className="text-[10px] text-zinc-800 hover:text-zinc-600 uppercase tracking-[4px] font-black">Admin Area</button>
        )}
      </footer>

      {/* Modals */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/90 backdrop-blur-sm" onClick={() => setShowLoginModal(false)}></div>
          <div className="relative glass-card w-full max-w-md p-10 rounded-[40px] border border-zinc-800 text-center">
            <Lock size={48} className="mx-auto mb-8 text-amber-500" />
            <input 
              type="password" 
              value={passwordInput}
              onChange={(e) => setPasswordInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-6 py-4 text-center text-xl focus:border-amber-500/50 outline-none mb-6" 
              placeholder="••••••••" 
            />
            <button onClick={handleLogin} className="w-full bg-zinc-100 text-zinc-950 font-black py-4 rounded-2xl">دخول</button>
          </div>
        </div>
      )}

      {selectedImage && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/95 backdrop-blur-sm lightbox-enter" onClick={() => setSelectedImage(null)}>
          <button className="absolute top-8 right-8 text-white p-2 bg-white/5 rounded-full"><X size={32} /></button>
          <ImageWithFallback src={selectedImage} className="max-w-full max-h-[90vh] object-contain rounded-xl shadow-2xl" alt="Preview" />
        </div>
      )}
    </div>
  );
}

export default App;
